<?php

declare(strict_types=1);
require __DIR__ . '/config/bootstrap.php';
$gameId = communityPositiveInt($_GET['id'] ?? null) ?? 0;
$game = $gameId ? loadGameDetail(db(), $gameId) : null;
if (!$game) { renderErrorPage(404, 'Game not found', 'This community hub is unavailable.'); }
$tabs = ['overview', 'discussions', 'guides', 'screenshots', 'reviews'];
$tab = is_string($_GET['tab'] ?? null) && in_array($_GET['tab'], $tabs, true) ? $_GET['tab'] : 'overview';
$page = communityPositiveInt($_GET['page'] ?? 1) ?? 1;
$viewerId = isAuthenticated() ? (int) currentUser()['id'] : null;
$pageTitle = $game['title'] . ' Community';
if ($tab === 'overview') { $content = loadCommunityCenter(db(), $gameId, $page); }
if ($tab === 'discussions') { $discussionFilters = parseDiscussionFilters($_GET, $gameId); $content = loadDiscussionTopics(db(), $discussionFilters); }
if ($tab === 'guides') { $content = loadGuideList(db(), ['sort' => 'popular', 'page' => $page, 'game_id' => $gameId], 8); }
if ($tab === 'reviews') { $content = loadGameReviews(db(), $gameId); }
require SKADI_ROOT . '/includes/header.php';
?>
<section class="community-page"><header><p class="eyebrow">Game Community Hub</p><h1><?= escape($game['title']) ?></h1><p><?= escape($game['short_description']) ?></p></header><nav class="community-tabs" aria-label="Community sections"><?php foreach ($tabs as $tabName): ?><a class="<?= $tab === $tabName ? 'active' : '' ?>" href="<?= escape(baseUrl('game-community.php?id=' . $gameId . '&tab=' . $tabName)) ?>" <?= $tab === $tabName ? 'aria-current="page"' : '' ?>><?= escape(ucfirst($tabName)) ?></a><?php endforeach; ?></nav>
<?php if ($tab === 'overview'): ?><div class="community-dashboard"><section class="community-panel"><div class="panel-heading"><h2>Discussions</h2><a href="?id=<?= $gameId ?>&tab=discussions">All</a></div><?php foreach ($content['topics'] as $item): ?><h3><a href="<?= escape(baseUrl('discussion.php?id=' . (int) $item['id'])) ?>"><?= escape($item['title']) ?></a></h3><?php endforeach; ?></section><section class="community-panel"><div class="panel-heading"><h2>Guides</h2><a href="?id=<?= $gameId ?>&tab=guides">All</a></div><?php foreach ($content['guides']['items'] as $item): ?><h3><a href="<?= escape(baseUrl('guide.php?id=' . (int) $item['id'])) ?>"><?= escape($item['title']) ?></a></h3><?php endforeach; ?></section><section class="community-panel"><div class="panel-heading"><h2>Posts</h2><a href="<?= escape(baseUrl('posts.php?game=' . $gameId)) ?>">All</a></div><?php foreach ($content['posts'] as $item): ?><p><a href="<?= escape(baseUrl('community-post.php?id=' . (int) $item['id'])) ?>"><?= escape(mb_strimwidth($item['body'], 0, 90, '…')) ?></a></p><?php endforeach; ?></section><section class="community-panel"><div class="panel-heading"><h2>Screenshots</h2><a href="?id=<?= $gameId ?>&tab=screenshots">All</a></div><div class="community-media-grid"><?php foreach ($content['screenshots'] as $item): ?><?php $url = safeGameMediaUrl($item['storage_path']); ?><?php if ($url): ?><img src="<?= escape($url) ?>" alt="<?= escape($item['alt_text']) ?>"><?php endif; ?><?php endforeach; ?></div></section></div>
<?php elseif ($tab === 'discussions'): ?><header class="section-heading"><h2>Discussions</h2><?php if ($viewerId): ?><a class="btn btn-primary" href="<?= escape(baseUrl('topic-edit.php?game=' . $gameId)) ?>">Start topic</a><?php endif; ?></header><form class="community-filter" method="get"><input type="hidden" name="id" value="<?= $gameId ?>"><input type="hidden" name="tab" value="discussions"><label>Search<input class="form-control" name="search" value="<?= escape($discussionFilters['search']) ?>" maxlength="100"></label><button class="btn btn-primary">Search</button></form><div class="discussion-list"><?php foreach ($content['items'] as $item): ?><article class="discussion-card"><h3><a href="<?= escape(baseUrl('discussion.php?id=' . (int) $item['id'])) ?>"><?= escape($item['title']) ?></a></h3><span><?= escape($item['category_name']) ?> · <?= (int) $item['reply_count'] ?> replies</span></article><?php endforeach; ?></div><nav class="catalog-pagination"><?php if ($content['page'] > 1): ?><a href="?<?= escape(http_build_query(['id' => $gameId, 'tab' => 'discussions', 'search' => $discussionFilters['search'], 'page' => $content['page'] - 1])) ?>">Previous</a><?php endif; ?><span>Page <?= $content['page'] ?> of <?= $content['pages'] ?></span><?php if ($content['page'] < $content['pages']): ?><a href="?<?= escape(http_build_query(['id' => $gameId, 'tab' => 'discussions', 'search' => $discussionFilters['search'], 'page' => $content['page'] + 1])) ?>">Next</a><?php endif; ?></nav>
<?php elseif ($tab === 'guides'): ?><header class="section-heading"><h2>Guides</h2><?php if ($viewerId): ?><a class="btn btn-primary" href="<?= escape(baseUrl('guide-edit.php?game=' . $gameId)) ?>">Write guide</a><?php endif; ?></header><div class="guide-grid"><?php foreach ($content['items'] as $item): ?><article class="guide-card"><div class="guide-card-body"><h3><a href="<?= escape(baseUrl('guide.php?id=' . (int) $item['id'])) ?>"><?= escape($item['title']) ?></a></h3><p><?= escape($item['summary']) ?></p></div></article><?php endforeach; ?></div><nav class="catalog-pagination"><?php if ($content['page'] > 1): ?><a href="?id=<?= $gameId ?>&tab=guides&page=<?= $content['page'] - 1 ?>">Previous</a><?php endif; ?><span>Page <?= $content['page'] ?> of <?= $content['pages'] ?></span><?php if ($content['page'] < $content['pages']): ?><a href="?id=<?= $gameId ?>&tab=guides&page=<?= $content['page'] + 1 ?>">Next</a><?php endif; ?></nav>
<?php elseif ($tab === 'screenshots'): ?><h2>Screenshots</h2><div class="screenshot-grid"><?php foreach ($game['screenshots'] as $item): ?><?php $url = safeGameMediaUrl($item['storage_path']); ?><?php if ($url): ?><a href="<?= escape($url) ?>"><img src="<?= escape($url) ?>" alt="<?= escape($item['alt_text']) ?>"></a><?php endif; ?><?php endforeach; ?></div>
<?php elseif ($tab === 'reviews'): ?><h2>Reviews</h2><p><a href="<?= escape(baseUrl('game.php?id=' . $gameId . '#reviews')) ?>">Write or edit an owner review on the store page.</a></p><div class="review-list"><?php foreach ($content as $review): ?><article class="review-card"><header><h3><?= escape($review['display_name']) ?></h3><span><?= (int) $review['rating'] ?>/10</span></header><p><?= nl2br(escape((string) $review['body'])) ?></p><?php renderReportForm('review', (int) $review['id'], 'game-community.php?id=' . $gameId . '&tab=reviews'); ?></article><?php endforeach; ?></div><?php endif; ?>
</section>
<?php require SKADI_ROOT . '/includes/footer.php'; ?>
